quiz.answer:
declare function require(name: string): any;
const input: string = require("fs").readFileSync(0, "utf8");

interface User {
  id: number;
  name: string;
  email: string;
}

type ParseResult =
  | { success: true; data: User }
  | { success: false; errors: string[] };

function kindOf(v: unknown): string {
  return v === null ? "null" : typeof v;
}

function parseUser(data: unknown): ParseResult {
  if (typeof data !== "object" || data === null || Array.isArray(data)) {
    return { success: false, errors: ["expected object, received " + (Array.isArray(data) ? "array" : kindOf(data))] };
  }
  const obj = data as Record<string, unknown>;
  const { id, name, email } = obj;
  const errors: string[] = [];
  if (typeof id !== "number") errors.push("expected number, received " + kindOf(id) + " → at id");
  if (typeof name !== "string") errors.push("expected string, received " + kindOf(name) + " → at name");
  if (typeof email !== "string") errors.push("expected string, received " + kindOf(email) + " → at email");
  if (typeof id === "number" && typeof name === "string" && typeof email === "string") {
    return { success: true, data: { id, name, email } };
  }
  return { success: false, errors };
}

const lines = input.split("\n").filter((l) => l !== "");
for (const line of lines) {
  const result = parseUser(JSON.parse(line));
  if (result.success) {
    console.log("OK " + result.data.name + " / " + result.data.email);
  } else {
    for (const e of result.errors) console.log("✖ " + e);
  }
}

```ts
import { z } from "zod";

const ProductSchema = z.object({
  id: z.number(),
  name: z.string(),
  price: z.number(),
});

type Product = z.infer<typeof ProductSchema>;

const broken = '{"id": 1, "name": "緑茶", "price": "150"}';
const result = ProductSchema.safeParse(JSON.parse(broken));

if (result.success) {
  console.log(result.data.name, result.data.price);
} else {
  console.log(z.prettifyError(result.error));
}
```
実行すると「✖ Invalid input: expected number, received string → at price」と表示されます。ポイントは、型 Product を手書きせず z.infer でスキーマから導出して二重管理のズレを防ぐこと、safeParse で失敗を例外ではなく if で扱うことです。境界での検証は失敗が起きて当然なので、正常系と同じ流れで失敗を処理できる safeParse が実務では使いやすい形です。
